export default function TaskInterface({ task, act }) {
  const t = task || {};
  const m = t.merchant || {};
  const intent = t.intent || {};
  const [pickedMethod, setPickedMethod] = React.useState(null);
  const [pickedReason, setPickedReason] = React.useState(null);
  const list = value => Array.isArray(value) ? value : [];
  const text = value => value === null || value === undefined || value === '' ? 'Not yet known' : typeof value === 'object' ? JSON.stringify(value) : String(value);
  const destinationLabel = value => value === 'original_payment' ? 'Original payment method' : value === 'store_credit' ? 'Store credit' : text(value);
  const methodLabel = value => value === 'qr_dropoff' ? 'Printer-free QR drop-off' : value === 'print_label' ? 'Print a shipping label' : text(value);
  const money = value => {
    if (typeof value !== 'number' || !m.currency) return 'Not yet known';
    try { return new Intl.NumberFormat('en-US', { style: 'currency', currency: m.currency }).format(value / 100); }
    catch (err) { return (value / 100).toFixed(2) + ' ' + text(m.currency); }
  };
  const overview = !task || t.status === 'not_started';
  const busy = !!t.progress || ['working', 'created', 'submitting'].includes(t.status);
  const locked = busy || !!t.receipt || overview;
  const desiredDestination = intent.refundDestination || 'original_payment';
  const desiredMethod = pickedMethod || intent.method || 'qr_dropoff';
  const desiredReason = pickedReason !== null ? pickedReason : (t.reason || '');
  const methods = list(m.methods).filter(item => item && ['print_label', 'qr_dropoff'].includes(item.value));
  const reasons = list(m.reasons).filter(item => item && item.value);
  const lines = list(m.lines);
  const selected = list(m.selectedLines).map(item => typeof item === 'object' && item ? item.id : item);
  const selectedNames = selected.map(id => { const line = lines.find(item => item.id === id); return line ? line.name : text(id); });
  const destinationConflict = !!m.refundDestination && m.refundDestination !== desiredDestination;
  const methodConflict = !!m.method && m.method !== desiredMethod;
  const lineConflict = selected.length > 0 && selected.some(id => { const line = lines.find(item => item.id === id); return line ? !/red.*shoes|shoes.*red/i.test(line.name || '') : id !== 'SHOE-RED-8'; });
  const checks = list(t.checks);
  const failedChecks = checks.some(item => ['failed', 'fail', 'conflict', 'mismatch', 'error'].includes(item.status));
  const conflict = destinationConflict || methodConflict || lineConflict || failedChecks;
  const missing = [];
  if (!m.method) missing.push('observed return method');
  if (!m.refundDestination) missing.push('observed refund destination');
  if (typeof m.deductionCents !== 'number' || !m.currency) missing.push('method fee and currency');
  if (typeof m.expectedRefundCents !== 'number') missing.push('expected refund');
  if (!selected.length) missing.push('selected return items');
  if (!desiredReason) missing.push('return reason');
  const fallbackScreens = [
    { id: '01M5RA468597ZJDYFH435PEFX5', name: 'Your next chapter, outside. | Northstar Outfitters' },
    { id: '01M5RA4P45QHTY16WZXG0B4KY3', name: 'Shop the collection | Northstar Outfitters' },
    { id: '01M5RA527TA07HKMCD7DKE7R13', name: 'How can we help? | Northstar Outfitters' },
    { id: '01M5RA5AYG9YAKGHYQYJ2ZJ8K2', name: 'Black jacket | Northstar Outfitters' }
  ];
  const fallbackFlows = [
    { id: '01M5RA52AH8QSDZR3NZC3RR7VE', name: 'Returns, exchanges & warranty', status: 'verified', exit: fallbackScreens[2].id },
    { id: '01M5RA4S73H4YA05CBSWFZP37R', name: 'Shop', status: 'verified', exit: fallbackScreens[1].id },
    { id: '01M5RA5B1D9364BMK1582C9GPD', name: 'Black jacket', status: 'verified', exit: fallbackScreens[3].id },
    { id: '01M5RA5N42J3NSF85HT36N7W6T', name: 'View product & options →', status: 'verified', exit: fallbackScreens[3].id }
  ];
  const discovery = t.discovery || {};
  const screens = Array.isArray(discovery.screens) ? discovery.screens : fallbackScreens;
  const flows = (Array.isArray(discovery.flows) ? discovery.flows : fallbackFlows).slice().sort((first, second) => Number(/return/i.test(second.name || '')) - Number(/return/i.test(first.name || '')));
  const statusText = t.receipt ? 'A receipt is available. The host shows the saved confirmation and verification result.' : busy ? text(t.progress || t.status) : overview ? 'Not started. No return has been submitted.' : conflict ? 'Your requested choices and the source do not match. Review and restore your choices.' : missing.length ? 'Some details are not yet known. Validate to check the source.' : 'Review the current terms, then validate. This is not a submitted return.';
  const send = (action, payload) => { if (!locked) act(action, payload); };
  return <main className="generated-root">
    <header className="generated-header">
      <p className="generated-eyebrow">Northstar Outfitters · Return assistant</p>
      <h1>Return the shoes.<br />Keep the jacket.</h1>
      <p className="generated-lead">A printer-free return, with the refund to your original payment method.</p>
      <p className="generated-scope">Sandbox · Synthetic records only · No production access</p>
    </header>
    <section className="generated-status" role="status" aria-live="polite" aria-atomic="true">{statusText}</section>
    {t.error && <section className="generated-warning" role="alert"><h2>Something needs attention</h2><p>{text(t.error)}</p></section>}
    {overview ? <>
      <section className="generated-panel">
        <p className="generated-eyebrow">Your supported task</p>
        <h2>Only the red running shoes</h2>
        <ul className="generated-list"><li>Return the red shoes.</li><li><strong>Keep jacket</strong> — it is not part of this return.</li><li>Use a printer-free method.</li><li>Preserve the original-payment refund preference.</li></ul>
        <p>Use the host’s “Start this task” control to begin. Nothing is started automatically.</p>
      </section>
      <section className="generated-panel"><h2>What the source observations show</h2><p>The printed-label draft requires a printer. The QR drop-off draft is printer-free, but changing to it changed the observed refund destination to store credit.</p><p><strong>That is a conflict, not your consent.</strong> We will keep your original-payment preference and check the current fee, refund, and destination before approval. Draft saves are not completed returns.</p><p className="generated-muted">Fees and refund amounts will appear from current task data after starting.</p></section>
      <section className="generated-panel"><h2>Observed routes</h2><p className="generated-muted">Exploration was incomplete because its budget ended. Reaching a page does not verify a completed transaction.</p>
        <div className="generated-flow-list">{flows.map((flow, index) => { const observation = flow.currentObservation || {}; const reached = observation.reached || flow.exit; const screen = screens.find(item => item.id === reached); return <section className="generated-flow" key={flow.id || index}><h3>{text(flow.name)}</h3><p>Reached: {screen ? text(screen.name) : reached ? text(reached) : 'Not recorded'}</p><p className="generated-muted">Recorded status: {text(observation.outcome || flow.status)} · Informational route only</p></section>; })}</div>
        {!flows.length && <p>No reached flows have been supplied.</p>}
        <p className="generated-muted">The product-page evidence changed between observations: size and help controls differed. Product browsing does not establish current return terms.</p>
      </section>
    </> : <>
      <div className="generated-grid">
        <section className="generated-panel"><p className="generated-eyebrow">01 · Your choices</p><h2>Return preferences</h2>
          <div className="generated-item"><strong>Return only red running shoes</strong><span>Your requested scope</span></div>
          <div className="generated-item"><strong>Keep jacket</strong><span>Not offered for return</span></div>
          <div className="generated-field"><label htmlFor="generated-reason">Return reason</label><select id="generated-reason" value={desiredReason} disabled={locked || !reasons.length} onChange={event => { const value = event.target.value; setPickedReason(value); send('choice', { reason: value }); }}><option value="">Choose a reason</option>{desiredReason && !reasons.some(item => item.value === desiredReason) && <option value={desiredReason}>{text(desiredReason)}</option>}{reasons.map(item => <option key={item.value} value={item.value}>{item.label}</option>)}</select>{!reasons.length && <p className="generated-muted">Reason options have not been supplied.</p>}</div>
          <div className="generated-field"><label htmlFor="generated-method">Return method</label><select id="generated-method" aria-describedby="generated-method-help" value={desiredMethod} disabled={locked || !methods.length} onChange={event => { const value = event.target.value; setPickedMethod(value); send('choice', { method: value }); }}>{!methods.some(item => item.value === desiredMethod) && <option value={desiredMethod}>{methodLabel(desiredMethod)}</option>}{methods.map(item => <option key={item.value} value={item.value}>{item.label}</option>)}</select><p id="generated-method-help" className="generated-muted">Selected preference: {methodLabel(desiredMethod)}. Changing the method may change the source refund destination; it does not change your refund preference.</p>{methods.filter(item => item.value === desiredMethod && item.detail).map(item => <p key={item.value}>{text(item.detail)}</p>)}{desiredMethod === 'print_label' && <p className="generated-warning">This method requires a printer and does not meet your printer-free goal.</p>}</div>
          <div className="generated-item"><strong>Requested refund destination</strong><span>{destinationLabel(desiredDestination)}</span></div>
        </section>
        <section className="generated-panel"><p className="generated-eyebrow">02 · Current source</p><h2>Review the exact terms</h2><p className="generated-muted">Observed values below are separate from your selected preferences.</p>
          <dl className="generated-terms"><div><dt>Items selected at source</dt><dd>{selectedNames.length ? selectedNames.join(', ') : 'Not yet known'}</dd></div><div><dt>Return method</dt><dd>{methodLabel(m.method)}</dd></div><div><dt>Method fee / deduction</dt><dd>{money(m.deductionCents)}</dd></div><div><dt>Refund destination</dt><dd>{destinationLabel(m.refundDestination)}</dd></div><div className="generated-total"><dt>Expected refund</dt><dd>{money(m.expectedRefundCents)}</dd></div></dl>
          {m.method === 'qr_dropoff' && <p>Show the synthetic QR code at a simulated drop-off counter. No printer is required.</p>}
          {m.method === 'print_label' && <p>Print and attach the synthetic label, then drop off the parcel.</p>}
          {missing.length > 0 && <div className="generated-note"><h3>Still unknown</h3><p>{missing.join('; ')}.</p><p>Dependent operations must wait for these details.</p></div>}
        </section>
      </div>
      {conflict && <section className="generated-warning" role="alert"><h2>Source choices need review</h2>{destinationConflict && <p><strong>Requested:</strong> {destinationLabel(desiredDestination)}<br /><strong>Observed:</strong> {destinationLabel(m.refundDestination)}</p>}{methodConflict && <p><strong>Requested:</strong> {methodLabel(desiredMethod)}<br /><strong>Observed:</strong> {methodLabel(m.method)}</p>}{lineConflict && <p><strong>Requested:</strong> red shoes only; keep jacket.<br /><strong>Observed:</strong> {selectedNames.join(', ')}.</p>}<p>Restore your choices, then validate again. Restoring is not a submission.</p><button className="generated-secondary" type="button" disabled={locked} onClick={() => send('check', { repair: true })}>Restore my choices</button></section>}
      <section className="generated-panel"><p className="generated-eyebrow">03 · Check before approval</p><h2>Validate your return</h2>
        {checks.length > 0 && <ul className="generated-checks">{checks.map((item, index) => <li key={index}><strong>{text(item.label)}</strong><span>Status: {text(item.status)}</span><span>Expected: {text(item.expected)}</span><span>Observed: {text(item.observed)}</span></li>)}</ul>}
        {t.validation && <div className="generated-note"><h3>Validation result</h3><p className="generated-wrap">{text(t.validation)}</p></div>}
        <p>Validation checks the source; it does not submit a return. The host will request explicit approval of the exact current terms and separately verify the saved confirmation.</p>
        <div className="generated-actions"><button className="generated-primary" type="button" disabled={locked} onClick={() => send('check', { repair: false })}>Validate</button>{!conflict && <button className="generated-secondary" type="button" disabled={locked} onClick={() => send('check', { repair: true })}>Restore my choices</button>}</div>
      </section>
    </>}
    <footer className="generated-footer">No real purchase, shipment, QR code, or refund is created in this sandbox. Approval and the final verified receipt are provided by the host.</footer>
  </main>;
}
